{"src/runTasks.mjs":"/** tasks是无参数异步函数数组，concurrency是并发上限；返回Promise。 */
export function runTasks(tasks, concurrency) {
  if (!Array.isArray(tasks)) {
    return Promise.reject(new TypeError('tasks must be an array of functions'));
  }

  const total = tasks.length;
  if (total === 0) {
    return Promise.resolve([]);
  }

  let limit = Number(concurrency);
  if (!Number.isFinite(limit) || limit < 1) {
    limit = 1;
  } else {
    limit = Math.floor(limit);
  }
  if (limit > total) {
    limit = total;
  }

  return new Promise((resolve, reject) => {
    const results = new Array(total);
    let nextIndex = 0;
    let running = 0;
    let settled = false;

    function fail(error) {
      if (settled) return;
      settled = true;
      reject(error);
    }

    function launch() {
      if (settled) return;

      while (running < limit && nextIndex < total) {
        const index = nextIndex++;
        const task = tasks[index];

        if (typeof task !== 'function') {
          fail(new TypeError('tasks[' + index + '] must be a function'));
          return;
        }

        running++;

        let promise;
        try {
          promise = Promise.resolve(task());
        } catch (error) {
          promise = Promise.reject(error);
        }

        promise.then(
          value => {
            if (settled) return;
            results[index] = value;
            running--;
            if (nextIndex >= total && running === 0) {
              settled = true;
              resolve(results);
            } else {
              launch();
            }
          },
          error => {
            running--;
            fail(error);
          }
        );
      }
    }

    launch();
  });
}
